func handleJobCatalogSearch(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	args := req.GetArguments()
	query := stringArg(args, "query")
	if query == "" {
		return mcplib.NewToolResultError("query is required"), nil
	}
	limit := intArg(args, "limit", 10, 1, 50)
	data, err := fetchCatalogSearch(query, limit, stringArg(args, "publisherId"), stringArg(args, "sort"))
	if err != nil {
		return mcpAPIError(err), nil
	}
	items := limitRawItems(extractResponseItems(data), limit)
	return jsonToolResult(map[string]any{
		"job":   "catalog_search",
		"query": query,
		"count": len(items),
		"items": compactProducts(items),
	}), nil
}

func handleJobCatalogPriceScan(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	args := req.GetArguments()
	query := stringArg(args, "query")
	if query == "" {
		return mcplib.NewToolResultError("query is required"), nil
	}
	limit := intArg(args, "limit", 10, 1, 50)
	data, err := fetchCatalogSearch(query, limit, "", "")
	if err != nil {
		return mcpAPIError(err), nil
	}
	products := compactProducts(limitRawItems(extractResponseItems(data), limit))
	sort.SliceStable(products, func(i, j int) bool {
		return numberForSort(products[i]["price"]) < numberForSort(products[j]["price"])
	})
	return jsonToolResult(map[string]any{
		"job":   "catalog_price_scan",
		"query": query,
		"count": len(products),
		"items": products,
	}), nil
}

