func handleJobCacheStatus(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	db, err := store.OpenReadOnly(dbPath())
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("opening database: %v", err)), nil
	}
	defer db.Close()

	status, err := db.Status()
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("reading status: %v", err)), nil
	}
	now := time.Now().UTC()
	resources := []string{"categories", "filters", "order-products", "products", "reviews", "special-offers"}
	var syncState []map[string]any
	for _, resource := range resources {
		cursor, synced, count, err := db.GetSyncState(resource)
		entry := map[string]any{"resource": resource}
		if err != nil {
			entry["error"] = err.Error()
		} else {
			entry["cursor"] = cursor
			entry["count"] = count
			if !synced.IsZero() {
				entry["last_synced"] = synced.UTC().Format(time.RFC3339)
				entry["age_seconds"] = int(now.Sub(synced.UTC()).Seconds())
			}
		}
		syncState = append(syncState, entry)
	}
	return jsonToolResult(map[string]any{
		"job":        "cache_status",
		"db_path":    dbPath(),
		"counts":     status,
		"sync_state": syncState,
	}), nil
}

func fetchCatalogSearch(query string, limit int, publisherID, sortKey string) (json.RawMessage, error) {
	c, err := newMCPClient()
	if err != nil {
		return nil, err
	}
	params := map[string]string{
		"keyword":  query,
		"pageSize": strconv.Itoa(limit),
	}
	if publisherID != "" {
		params["publisherId"] = publisherID
	}
	if sortKey != "" {
		params["sort"] = sortKey
	}
	return c.Get("/products", params)
}

func fetchLibraryPage(limit int, archived bool) ([]json.RawMessage, error) {
	c, err := newMCPClient()
	if err != nil {
		return nil, err
	}
	data, err := c.Get("/order_products", map[string]string{
		"getChecksum": "1",
		"getFilters":  "0",
		"page":        "1",
		"pageSize":    strconv.Itoa(limit),
		"library":     "1",
		"archived":    boolIntString(archived),
	})
	if err != nil {
		return nil, err
	}
	return extractResponseItems(data), nil
}

func fetchLibraryProduct(orderProductID string) (json.RawMessage, error) {
	items, err := fetchLibraryPage(100, false)
	if err != nil {
		return nil, err
	}
	for _, item := range items {
		if libraryProductID(item) == orderProductID {
			return item, nil
		}
	}
	return nil, fmt.Errorf("order product %s not found on the first library page; run order-products directly if it is archived or deeper in the library", orderProductID)
}

func jsonToolResult(value any) *mcplib.CallToolResult {
	data, err := json.Marshal(value)
	if err != nil {
		return mcplib.NewToolResultError(err.Error())
	}
	return mcplib.NewToolResultText(string(data))
}

func mcpAPIError(err error) *mcplib.CallToolResult {
	return mcplib.NewToolResultError(cliutil.SanitizeErrorBody(err.Error()))
}

func firstResponseItem(data json.RawMessage) json.RawMessage {
	items := extractResponseItems(data)
	if len(items) > 0 {
		return items[0]
	}
	return data
}

func extractResponseItems(data json.RawMessage) []json.RawMessage {
	var items []json.RawMessage
	if json.Unmarshal(data, &items) == nil {
		return items
	}
	var envelope map[string]json.RawMessage
	if json.Unmarshal(data, &envelope) != nil {
		return []json.RawMessage{data}
	}
	for _, key := range []string{"data", "results", "items", "records", "entries"} {
		if raw, ok := envelope[key]; ok {
			if json.Unmarshal(raw, &items) == nil {
				return items
			}
		}
	}
	return []json.RawMessage{data}
}

func limitRawItems(items []json.RawMessage, limit int) []json.RawMessage {
	if limit > 0 && len(items) > limit {
		return items[:limit]
	}
	return items
}

func compactProducts(items []json.RawMessage) []map[string]any {
	out := make([]map[string]any, 0, len(items))
	for _, item := range items {
		out = append(out, compactProduct(item))
	}
	return out
}

func compactProduct(item json.RawMessage) map[string]any {
	obj := objectFromRaw(item)
	attrs := objectValue(obj["attributes"])
	desc := objectValue(attrs["description"])
	return cleanMap(map[string]any{
		"id":            stringValue(obj["id"]),
		"product_id":    firstNonEmpty(attrs["productId"], attrs["product_id"]),
		"name":          firstNonEmpty(desc["name"], attrs["name"], obj["name"]),
		"slug":          firstNonEmpty(desc["slug"], attrs["slug"]),
		"price":         firstNonEmpty(attrs["specialPrice"], attrs["price"], attrs["lowestDigitalPrice"], attrs["lowestAnyPrice"]),
		"rating":        attrs["rating"],
		"rating_count":  attrs["ratingCount"],
		"publisher_id":  attrs["publisherId"],
		"formats":       productFormats(attrs["options"]),
		"short_summary": firstNonEmpty(desc["shortDescription"], attrs["shortDescription"]),
	})
}

func compactLibraryProducts(items []json.RawMessage) []map[string]any {
	out := make([]map[string]any, 0, len(items))
	for _, item := range items {
		out = append(out, compactLibraryProduct(item))
	}
	return out
}

func compactLibraryProduct(item json.RawMessage) map[string]any {
	obj := objectFromRaw(item)
	attrs := objectValue(obj["attributes"])
	files := arrayValue(attrs["files"])
	return cleanMap(map[string]any{
		"id":                 stringValue(obj["id"]),
		"order_product_id":   firstNonEmpty(attrs["orderProductId"], attrs["order_product_id"]),
		"order_id":           firstNonEmpty(attrs["orderId"], attrs["order_id"]),
		"product_id":         firstNonEmpty(attrs["productId"], attrs["product_id"]),
		"name":               firstNonEmpty(attrs["name"], obj["name"]),
		"archived":           attrs["archived"],
		"file_count":         len(files),
		"final_price":        attrs["finalPrice"],
		"file_last_modified": firstNonEmpty(attrs["fileLastModified"], attrs["file_last_modified"]),
	})
}

func compactLibraryFiles(item json.RawMessage) []map[string]any {
	obj := objectFromRaw(item)
	attrs := objectValue(obj["attributes"])
	files := arrayValue(attrs["files"])
	out := make([]map[string]any, 0, len(files))
	for _, file := range files {
		f := objectValue(file)
		out = append(out, cleanMap(map[string]any{
			"index":          f["index"],
			"title":          firstNonEmpty(f["title"], f["filename"]),
			"filename":       f["filename"],
			"size_mb":        firstNonEmpty(f["sizeMB"], f["size_mb"]),
			"download_id":    firstNonEmpty(f["orderProductDownloadId"], f["order_product_download_id"]),
			"checksum_count": len(arrayValue(f["checksums"])),
		}))
	}
	return out
}

func compactDownloadStatus(data json.RawMessage) map[string]any {
	obj := objectFromRaw(firstResponseItem(data))
	attrs := objectValue(obj["attributes"])
	if len(attrs) == 0 {
		attrs = obj
	}
	return cleanMap(map[string]any{
		"status": firstNonEmpty(attrs["status"], obj["status"]),
		"url":    firstNonEmpty(attrs["url"], attrs["downloadUrl"], obj["url"]),
		"raw":    json.RawMessage(data),
	})
}

func libraryProductID(item json.RawMessage) string {
	obj := objectFromRaw(item)
	attrs := objectValue(obj["attributes"])
	for _, value := range []any{attrs["orderProductId"], attrs["order_product_id"], obj["orderProductId"], obj["id"]} {
		if s := stringValue(value); s != "" {
			if strings.Contains(s, "/") {
				parts := strings.Split(strings.TrimRight(s, "/"), "/")
				s = parts[len(parts)-1]
			}
			return s
		}
	}
	return ""
}

func productFormats(value any) []string {
	var formats []string
	for _, raw := range arrayValue(value) {
		option := objectValue(raw)
		if name := stringValue(firstNonEmpty(option["optionValueName"], option["description"], option["type"])); name != "" {
			formats = append(formats, name)
		}
	}
	return formats
}

func objectFromRaw(raw json.RawMessage) map[string]any {
	var obj map[string]any
	_ = json.Unmarshal(raw, &obj)
	return obj
}

func objectValue(value any) map[string]any {
	if m, ok := value.(map[string]any); ok {
		return m
	}
	return map[string]any{}
}

func arrayValue(value any) []any {
	if items, ok := value.([]any); ok {
		return items
	}
	return nil
}

func cleanMap(in map[string]any) map[string]any {
	out := make(map[string]any, len(in))
	for k, v := range in {
		switch value := v.(type) {
		case nil:
			continue
		case string:
			if strings.TrimSpace(value) == "" {
				continue
			}
		case []string:
			if len(value) == 0 {
				continue
			}
		case []map[string]any:
			if len(value) == 0 {
				continue
			}
		}
		out[k] = v
	}
	return out
}

func firstNonEmpty(values ...any) any {
	for _, value := range values {
		if s, ok := value.(string); ok {
			if strings.TrimSpace(s) != "" {
				return s
			}
			continue
		}
		if value != nil {
			return value
		}
	}
	return nil
}

func stringArg(args map[string]any, name string) string {
	return strings.TrimSpace(stringValue(args[name]))
}

func stringValue(value any) string {
	switch v := value.(type) {
	case string:
		return v
	case fmt.Stringer:
		return v.String()
	case float64:
		if v == float64(int64(v)) {
			return strconv.FormatInt(int64(v), 10)
		}
		return strconv.FormatFloat(v, 'f', -1, 64)
	case int:
		return strconv.Itoa(v)
	case int64:
		return strconv.FormatInt(v, 10)
	case json.Number:
		return v.String()
	default:
		if value == nil {
			return ""
		}
		return fmt.Sprintf("%v", value)
	}
}

func intArg(args map[string]any, name string, fallback, minValue, maxValue int) int {
	value := fallback
	switch v := args[name].(type) {
	case float64:
		value = int(v)
	case int:
		value = v
	case int64:
		value = int(v)
	case string:
		if parsed, err := strconv.Atoi(strings.TrimSpace(v)); err == nil {
			value = parsed
		}
	}
	if value < minValue {
		value = minValue
	}
	if maxValue > 0 && value > maxValue {
		value = maxValue
	}
	return value
}

func boolArg(args map[string]any, name string, fallback bool) bool {
	switch v := args[name].(type) {
	case bool:
		return v
	case string:
		parsed, err := strconv.ParseBool(strings.TrimSpace(v))
		if err == nil {
			return parsed
		}
	case float64:
		return v != 0
	}
	return fallback
}

func boolIntString(value bool) string {
	if value {
		return "1"
	}
	return "0"
}

func numberForSort(value any) float64 {
	switch v := value.(type) {
	case float64:
		return v
	case int:
		return float64(v)
	case int64:
		return float64(v)
	case json.Number:
		n, _ := v.Float64()
		return n
	case string:
		n, err := strconv.ParseFloat(strings.TrimSpace(v), 64)
		if err == nil {
			return n
		}
	}
	return 1e18
}
